const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=new Date().toISOString().slice(0,10),ago=n=>new Date(Date.now()-n*86400000).toISOString().slice(0,10);
const seed={name:'Distrito Social Gastrobar',city:'Bogotá D.C.',address:'Calle 85 # 12–40 · Chapinero',department:'Bogotá D.C.',phone:'+57 601 123 4567',contactEmail:'contacto@distritosocial.demo',ciiu:'5630 · Expendio de bebidas alcohólicas',code:'DEMO-0001',music:true,hotel:false,issued:ago(27),renewed:true,docs:{},events:[],email:'',alerts:true};const seedCompany={nit:'901.234.567-8',razon:'Distrito Social S.A.S.'};
const KEY='cede-pilot-v1';
const blankSite=()=>({name:'',city:'',department:'',address:'',phone:'',contactEmail:'',ciiu:'5630 · Expendio de bebidas alcohólicas',music:true,hotel:false,issued:today,renewed:true,docs:{},events:[],email:'',alerts:true});
function upgrade(raw){if(raw&&raw.sites&&raw.order&&raw.current)return raw;const base={company:{...seedCompany},sites:{},order:['s1'],current:'s1'};if(raw&&!raw.sites){const {nit,...resto}=raw;if(nit)base.company.nit=nit;if(raw.name)base.company.razon=raw.name;base.sites.s1={...seed,...resto,code:'DEMO-0001'}}else base.sites.s1={...seed,code:'DEMO-0001'};return base}
let store,state;try{store=JSON.parse(localStorage.getItem(KEY)||'null')}catch{store=null}
store=upgrade(store);state=store.sites[store.current]||store.sites[store.order[0]];state.music=true;state.renewed=true;
const save=()=>localStorage.setItem(KEY,JSON.stringify(store));
const company=()=>store.company;
const sites=()=>store.order.filter(id=>store.sites[id]).map(id=>[id,store.sites[id]]);
const siteCode=()=>state.code||'DEMO-0001';
function nextCode(){const usados=new Set(Object.values(store.sites).map(x=>x.code));let n=1;while(usados.has('DEMO-'+String(n).padStart(4,'0')))n++;return 'DEMO-'+String(n).padStart(4,'0')}
function switchSite(id){if(!store.sites[id])return;store.current=id;state=store.sites[id];state.music=true;state.renewed=true;save();render();toast('Ahora ves: '+state.name)}
function newSite(){openModal(`<h2>Agregar establecimiento</h2><p class="muted">Quedará asociado al NIT ${esc(company().nit)} de ${esc(company().razon)}.</p><form onsubmit="siteCreate(event)"><label>Nombre del establecimiento<input id="sname" required maxlength="100" placeholder="Ej.: Sede Chapinero"></label><label>Municipio<input id="scity" required maxlength="100" placeholder="Ej.: Medellín"></label><label for="sdept">Departamento</label><select id="sdept" required style="max-width:100%"><option value="">Selecciona un departamento</option>${departments.map(d=>`<option>${d}</option>`).join('')}</select><label>Dirección<input id="saddress" required maxlength="140"></label><label>Teléfono de contacto<input id="sphone" type="tel" maxlength="40" placeholder="Opcional"></label><label>Correo de contacto<input id="scontact" type="email" maxlength="120" placeholder="Opcional"></label><p class="muted">Cada establecimiento tiene su propio expediente, su código y sus buenas prácticas.</p><div class="actions"><button class="btn primary">Crear establecimiento</button><button type="button" class="btn" onclick="$('#modal').close()">Cancelar</button></div></form>`)}
function siteCreate(e){e.preventDefault();const name=$('#sname').value.trim(),city=$('#scity').value.trim(),dept=$('#sdept').value,address=$('#saddress').value.trim();if(!name||!city||!dept||!address)return toast('Completa nombre, municipio, departamento y dirección.');const id='s'+Date.now().toString(36);store.sites[id]={...blankSite(),name,city,department:dept,address,phone:$('#sphone').value.trim(),contactEmail:$('#scontact').value.trim(),code:nextCode()};store.order.push(id);store.current=id;state=store.sites[id];save();$('#modal').close();location.hash='inicio';render();toast('Establecimiento creado: '+name)}
function removeSite(id){if(store.order.length<2)return toast('Debe quedar al menos un establecimiento.');const nombre=store.sites[id]?.name||'';delete store.sites[id];store.order=store.order.filter(x=>x!==id);if(store.current===id){store.current=store.order[0];state=store.sites[store.current]}save();$('#modal').close();render();toast('Establecimiento retirado del piloto: '+nombre)}
const departments=['Amazonas','Antioquia','Arauca','Archipiélago de San Andrés, Providencia y Santa Catalina','Atlántico','Bogotá D.C.','Bolívar','Boyacá','Caldas','Caquetá','Casanare','Cauca','Cesar','Chocó','Córdoba','Cundinamarca','Guainía','Guaviare','Huila','La Guajira','Magdalena','Meta','Nariño','Norte de Santander','Putumayo','Quindío','Risaralda','Santander','Sucre','Tolima','Valle del Cauca','Vaupés','Vichada'];
const items=[['rut','Registro Único Tributario (RUT)','DIAN','Complementario · tributario','Inscripción y actualización del RUT con la actividad económica y las responsabilidades tributarias del establecimiento.','pending'],['factura','Facturación electrónica','DIAN','Complementario · tributario','Habilitación y expedición de factura electrónica de venta, o del documento equivalente que corresponda a la operación.','pending'],['rit','Registro de Información Tributaria (RIT)','Secretaría de Hacienda distrital o municipal','Complementario · tributario','Inscripción y actualización en el registro tributario territorial del municipio donde opera el establecimiento, cuando este lo exige.','pending'],['retie','Certificación RETIE / RETILAP','Profesional u organismo de inspección acreditado','Complementario · seguridad','Certificación de la instalación eléctrica y de la iluminación conforme a los reglamentos técnicos RETIE y RETILAP.','pending'],['dea','Zona de cardioprotección (DEA)','Secretaría de Salud territorial','Complementario · seguridad','Desfibrilador externo automático disponible y con mantenimiento, señalización visible y personal entrenado, según el aforo y la actividad.','pending'],['vertical','Revisión de ascensores y puertas eléctricas','Organismo de inspección acreditado','Complementario · seguridad','Certificación vigente de los equipos de transporte vertical y de las puertas eléctricas. Aplica solo si el establecimiento cuenta con esos equipos.','pending'],['precios','Lista de precios visible al consumidor','Superintendencia de Industria y Comercio','Complementario · consumidor','Precios de productos y servicios informados de forma visible y en pesos colombianos, con la advertencia de que la propina es voluntaria.','pending'],['poliza','Póliza de responsabilidad civil y extracontractual','Aseguradora','Complementario · recomendado','Cobertura vigente frente a daños a terceros. Asobares la recomienda; su exigencia depende del contrato de arrendamiento, del municipio o del tipo de evento.','pending'],['suelo','Uso del suelo y destinación','Planeación municipal / distrital','Artículo 87 · Previo · numeral 1','Consulta asociada a dirección, actividad y destinación de la edificación. La evidencia no reemplaza el cumplimiento material.','ok'],['mercantil','Matrícula y certificado mercantil','Cámara de Comercio de la jurisdicción / RUES','Artículo 87 · Previo · numeral 2','Separar renovación anual de matrícula y antigüedad del certificado. C.E.D.E. propone refrescar la evidencia cada 30 días.','ok'],['apertura','Comunicación de apertura','Policía Nacional · estación de la jurisdicción','Artículo 87 · Previo · numeral 3','Constancia de comunicación de apertura por el canal habilitado por la Policía. No equivale a una licencia.','ok'],['ruido','Niveles de intensidad auditiva','Autoridad ambiental y autoridades competentes','Artículo 87 · Ejecución · numeral 1','Requiere cumplimiento continuo y verificación técnica cuando corresponda. Un documento no acredita el ruido actual.','visit'],['horarios','Horarios de funcionamiento','Alcaldía / Secretaría de Gobierno','Artículo 87 · Ejecución · numeral 2','Regla territorial por zona y actividad. Pendiente parametrizar la norma local vigente; no se presume un horario nacional.','visit'],['seguridad','Condiciones de seguridad','Autoridad local competente / Bomberos, según competencia','Artículo 87 · Ejecución · numeral 3','Evidencias e inspección según el régimen aplicable. No se inventa un certificado universal obligatorio.','ok'],['sanidad','Condiciones sanitarias','Secretaría de Salud territorial','Artículo 87 · Ejecución · numeral 3','Conceptos y actuaciones sanitarias aplicables a la actividad, sujetos a verificación de condiciones reales.','pending'],['ambiente','Condiciones ambientales','Autoridad ambiental territorial','Artículo 87 · Ejecución · numeral 3','Obligaciones ambientales del establecimiento: manejo de residuos, vertimientos, emisiones, publicidad exterior visual y control del ruido hacia el vecindario. Varían según actividad y jurisdicción; exigen verificación material, no solo un documento.','visit'],['objeto','Actividad económica registrada','Cámara de Comercio / autoridad de inspección','Artículo 87 · Ejecución · numeral 4','Contrastar actividad real con objeto y actividades registrados.','ok'],['autor','Derechos de autor y conexos','Organización Sayco Acinpro / titulares o gestores habilitados','Artículo 87 · Ejecución · numeral 5','Comprobante de pago al día cuando se ejecutan obras musicales protegidas causantes de pago. OSA es un posible interlocutor; debe verificarse repertorio y legitimación.','ok'],['rnt','Registro Nacional de Turismo','Cámaras de Comercio / sistema RNT · MinCIT','Artículo 87 · Ejecución · numeral 6','Alojamiento u hospitalidad según el artículo 87; revisar adicionalmente el régimen turístico especial. No se presume obligatorio para todos los bares.','na']];
function status(r){if((r[0]==='autor'&&!state.music)||(r[0]==='rnt'&&!state.hotel))return 'na';if(state.checks?.[r[0]]==='fail')return 'fail';const dd=state.docs[r[0]];if(dd?.expires&&dd.expires<today)return 'stale';if(state.docs[r[0]]&&!state.checks?.[r[0]])return 'review';if(r[0]==='mercantil'){if(!state.renewed)return 'pending';const age=Math.floor((Date.now()-new Date(state.issued+'T00:00:00'))/86400000);return age>30?'stale':state.checks?.mercantil==='pass'?'pass':age>=23?'soon':'ok'}if(state.checks?.[r[0]]==='pass')return dd?.expires&&daysTo(dd.expires)<=30?'soon':'pass';return r[5]==='na'?'pending':r[5]}
const daysTo=d=>Math.ceil((new Date(d+'T00:00:00')-Date.now())/86400000);
const labels={pass:'Verificado · simulación',fail:'No cumple · simulación',ok:'Evidencia demo',soon:'Actualizar pronto',stale:'Actualizar evidencia',pending:'Pendiente',visit:'Verificación en sitio',na:'No aplica al perfil',review:'Por validar'};const badge=s=>`<span class="badge ${['soon','stale','pending','review'].includes(s)?'warn':s==='pass'?'pass':s==='fail'?'fail':s==='visit'?'blue':s==='na'?'gray':''}">${labels[s]}</span>`;
const nav=[['inicio','◫','Mi establecimiento'],['documentos','▤','Expediente digital'],['cedula','▦','Mi C.E.D.E.'],['practicas','☆','Buenas prácticas'],['alertas','◷','Alertas y vigencias'],['horarios','◷','Horarios por municipio'],['biblioteca','▤','Biblioteca'],['entidades','⬡','Entidades'],['verificar','⌕','Consulta IVC'],['modelo','≡','Modelo del piloto']];
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}function head(k,t,d,action=''){return `<div class="heading"><div><span class="eyebrow">${k}</span><h1>${t}</h1><p class="muted">${d}</p></div>${action}</div>`}function checkRow(r){const st=status(r),tone=st==='pass'?'green':st==='fail'?'red':st==='na'?'gray':'yellow';return `<div class="docrow"><div><span class="dot ${tone}"></span></div><div><h3>${r[1]}${state.docs[r[0]]?.file?' <span class="badge gray">📎 PDF</span>':''}</h3><p>${r[2]}</p></div>${badge(st)}</div>`}
const FILEDB='cede-files',MAXFILE=10*1024*1024;
const idb=()=>new Promise((res,rej)=>{if(!window.indexedDB)return rej(new Error('sin indexedDB'));const r=indexedDB.open(FILEDB,1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});
const fileStore=(key,blob)=>idb().then(db=>new Promise((res,rej)=>{const t=db.transaction('files','readwrite');t.objectStore('files').put(blob,key);t.oncomplete=()=>res(true);t.onerror=()=>rej(t.error)}));
const fileRead=key=>idb().then(db=>new Promise((res,rej)=>{const t=db.transaction('files','readonly'),q=t.objectStore('files').get(key);q.onsuccess=()=>res(q.result||null);q.onerror=()=>rej(q.error)}));
const fileDrop=key=>idb().then(db=>new Promise((res,rej)=>{const t=db.transaction('files','readwrite');t.objectStore('files').delete(key);t.oncomplete=()=>res(true);t.onerror=()=>rej(t.error)}));
const fileSize=n=>n>=1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB';
async function fileOpen(key){try{const b=await fileRead(key);if(!b)return toast('El archivo ya no está guardado en este navegador.');const u=URL.createObjectURL(b);window.open(u,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(u),60000)}catch{toast('No se pudo abrir el archivo.')}}
async function takeFile(key,input){const f=input?.files?.[0];if(!f)return null;if(f.type!=='application/pdf'&&!/\.pdf$/i.test(f.name)){toast('Solo se admiten archivos PDF.');return 'error'}if(f.size>MAXFILE){toast('El PDF supera 10 MB.');return 'error'}try{await fileStore(key,f);return {name:f.name,size:f.size,added:today}}catch{toast('Este navegador no permitió guardar el archivo.');return 'error'}}
function fileField(key,file){return `<label for="docfile">Documento en PDF (opcional)</label><input id="docfile" type="file" accept="application/pdf">${file?`<div class="rule"><b>📎 ${esc(file.name)}</b> · ${fileSize(file.size)} · cargado el ${esc(file.added)}<div class="actions"><button type="button" class="btn small" onclick="fileOpen('${key}')">Ver PDF</button><button type="button" class="btn small" onclick="dropFile('${key}')">Quitar</button></div></div>`:''}<p class="muted">El archivo se guarda únicamente en este navegador, no se envía a ningún servidor. Máximo 10 MB.</p>`}
async function dropFile(key){const [tipo,id]=key.split(':');await fileDrop(key).catch(()=>{});if(tipo==='doc'&&state.docs[id])delete state.docs[id].file;if(tipo==='practica'&&state.practices?.[id])delete state.practices[id].file;save();$('#modal').close();render();toast('Archivo retirado de este navegador.')}
