const wa=asunto=>`https://wa.me/${WHATSAPP}?text=${encodeURIComponent('Hola, escribo desde la plataforma C.E.D.E. de Asobares. Necesito ayuda con '+asunto+'.')}`;
function row(r,editable=true){const st=status(r);return `<div class="docrow"><div class="docicon">▤</div><div><h3>${r[1]}${state.docs[r[0]]?.file?' <span class="badge gray">📎 PDF</span>':''}</h3><p>${r[2]}</p>${badge(st)}</div><button class="btn small" onclick="detail('${r[0]}',${editable})">${editable?'Gestionar':'Detalle'}</button></div>`}function identity(){return `<div class="card identity" id="cedulacard"><span class="eyebrow">Cédula digital empresarial</span><h2>C.E.D.E.</h2><p class="holder">${esc(state.name)}</p><dl class="idfacts"><div><dt>NIT</dt><dd>${esc(company().nit)}</dd></div><div><dt>Municipio</dt><dd>${esc(state.city)}</dd></div></dl><div class="qrbox"><img src="qr.svg" alt="QR de consulta demostrativa C.E.D.E. ${esc(siteCode())}"></div><div class="serial">CEDE · ${esc(siteCode())}</div><a class="btn light" href="#verificar">Consultar cédula ↗</a><p style="text-align:center;margin:12px 0 0;font-size:11px">Identidad piloto · ${assessment().title}</p></div>`}
function cardFile(ext){return 'cede-'+siteCode()+'.'+ext}
function printCard(){document.body.classList.add('printcard');setTimeout(()=>{window.print();document.body.classList.remove('printcard')},60)}
function downloadCard(){const W=1000,H=1560,cv=document.createElement('canvas');cv.width=W;cv.height=H;const g=cv.getContext('2d');const img=new Image();
img.onload=()=>{g.fillStyle='#173d34';g.fillRect(0,0,W,H);g.fillStyle='#d9f16e';g.fillRect(0,0,W,14);g.textAlign='center';
const F=(w,sz)=>`${w} ${sz}px -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif`;
g.fillStyle='#d9f16e';g.font=F(600,26);g.fillText('CÉDULA DIGITAL EMPRESARIAL',W/2,120);
g.fillStyle='#fff';g.font=F(700,86);g.fillText('C.E.D.E.',W/2,220);
const box=520,bx=(W-box)/2,by=290;g.fillStyle='#fff';if(g.roundRect){g.beginPath();g.roundRect(bx,by,box,box,28);g.fill()}else g.fillRect(bx,by,box,box);
g.drawImage(img,bx+40,by+40,box-80,box-80);
let y=by+box+90;g.fillStyle='#fff';g.font=F(700,46);
const words=String(state.name).split(' ');let line='',lines=[];words.forEach(w=>{const t=line?line+' '+w:w;if(g.measureText(t).width>W-140&&line){lines.push(line);line=w}else line=t});if(line)lines.push(line);
lines.slice(0,2).forEach((l,i)=>g.fillText(l,W/2,y+i*58));y+=lines.slice(0,2).length*58+24;
g.fillStyle='#c5d7cf';g.font=F(400,30);g.fillText('NIT '+(company().nit||'—'),W/2,y);y+=46;g.fillText(String(state.city||''),W/2,y);y+=64;
g.fillStyle='#d9f16e';g.font=`600 34px ui-monospace,SFMono-Regular,Menlo,monospace`;g.fillText('CEDE · '+siteCode(),W/2,y);
g.fillStyle='#9fb5ab';g.font=F(400,24);g.fillText('Piloto demostrativo · cede.asobares.org',W/2,H-90);g.fillText('Sin validación oficial del establecimiento',W/2,H-54);
cv.toBlob(b=>{if(!b)return toast('No se pudo generar la imagen.');const a=document.createElement('a');const u=URL.createObjectURL(b);a.href=u;a.download=cardFile('png');a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);toast('Imagen de la cédula descargada.')},'image/png')};
img.onerror=()=>toast('No se pudo cargar el QR para generar la imagen.');img.src='qr.svg'}
function renewals(){const rows=items.filter(r=>state.docs[r[0]]?.expires).map(r=>[r,state.docs[r[0]],daysTo(state.docs[r[0]].expires)]).sort((a,b)=>a[2]-b[2]);if(!rows.length)return '<p class="muted">Ningún documento tiene fecha de renovación registrada. Puedes indicarla al guardar la referencia de cada requisito.</p>';return rows.map(([r,d,left])=>`<div class="docrow"><div>◷</div><div><h3>${r[1]}</h3><p>Renovar antes de: ${esc(d.expires)}</p></div><span class="badge ${left<0?'fail':left<=30?'warn':'pass'}">${left<0?`Vencido hace ${-left} días`:left<=30?`Vence en ${left} días`:`Vigente · ${left} días`}</span></div>`).join('')}
function notice(){if(!state.alerts)return '';const days=Math.floor((Date.now()-new Date(state.issued+'T00:00:00'))/86400000);return `<div class="notice"><div><strong>${days>=30?'Actualiza tu evidencia mercantil':'Tu certificado mercantil requiere seguimiento'}</strong>Emitido hace ${days} días. Umbral interno C.E.D.E.: 30 días; la matrícula se renueva anualmente.</div><button class="btn small" onclick="detail('mercantil',true)">Revisar certificado →</button></div>`}
const nextSteps={fail:['Corrige el incumplimiento','la simulación registra un incumplimiento en este control.','Abrir control'],stale:['Actualiza la evidencia','la evidencia superó los 30 días propuestos por C.E.D.E.','Actualizar evidencia'],pending:['Registra la evidencia','este control todavía no tiene una referencia documental.','Agregar evidencia'],review:['Simula la verificación','hay una referencia aportada que falta validar.','Abrir control'],soon:['Renueva la evidencia','la evidencia se acerca al límite de 30 días.','Actualizar evidencia'],ok:['Simula la verificación','la evidencia demo aún no tiene una verificación registrada.','Abrir control'],visit:['Requiere verificación en sitio','este control exige comprobación material, no solo un documento.','Abrir control']};
function nextStep(){const order=Object.keys(nextSteps);return items.filter(r=>!['na','pass'].includes(status(r))).sort((a,b)=>order.indexOf(status(a))-order.indexOf(status(b)))[0]}
function nextStepCard(){const r=nextStep();if(!r)return `<div class="card"><span class="eyebrow">Próximo paso</span><h3 style="margin-top:12px">No tienes pendientes</h3><p class="muted">Todos los controles aplicables están verificados en esta simulación. Mantén las evidencias al día.</p><a class="btn small" href="#documentos">Ver expediente</a></div>`;const [title,text,label]=nextSteps[status(r)];return `<div class="card"><span class="eyebrow">Próximo paso</span><h3 style="margin-top:12px">${title}</h3><p class="muted">${esc(r[1])}: ${text}</p><button class="btn small" onclick="detail('${r[0]}',true)">${label}</button></div>`}
function render(){const route=location.hash.slice(1)||'inicio';$('#nav').innerHTML=nav.map(([id,icon,title])=>`<a href="#${id}" class="${route===id?'active':''}"><span>${icon}</span>${title}</a>`).join('');$('#crumb').textContent=nav.find(x=>x[0]===route)?.[2]||'Consulta';const active=items.filter(r=>status(r)!=='na'),evidence=active.filter(r=>['ok','soon','stale','pass'].includes(status(r))).length;let out='';
if(route==='inicio'){out=head('Mi espacio empresarial','Tu negocio, en un solo lugar.','Consulta tus evidencias y anticipa las próximas actualizaciones.',`<button class="btn" onclick="profile()">Editar establecimiento</button>`)+traffic()+notice()+`<div class="card"><div class="sectionhead" style="margin-top:0"><h2>${esc(company().razon)}</h2><button class="btn small" onclick="newSite()">Agregar establecimiento</button></div><p class="muted">NIT ${esc(company().nit)} · ${store.order.length} ${store.order.length===1?'establecimiento asociado':'establecimientos asociados'}</p>${sites().map(([id,x])=>`<div class="docrow"><div><span class="dot ${id===store.current?'green':'gray'}"></span></div><div><h3>${esc(x.name||'Establecimiento sin nombre')}${id===store.current?' <span class="badge pass">Activo</span>':''}</h3><p>${esc(x.city||'Sin municipio')}${x.department?' · '+esc(x.department):''} · ${esc(x.code||'')}</p></div>${id===store.current?`<button class="btn small" onclick="profile()">Editar</button>`:`<button class="btn small" onclick="switchSite('${id}')">Abrir</button>`}</div>`).join('')}${store.order.length>1?`<p class="muted" style="margin-top:14px">Cada establecimiento conserva su propio expediente, su código C.E.D.E. y sus buenas prácticas. <button class="btn small" onclick="removeSite('${store.current}')">Retirar el establecimiento activo</button></p>`:''}</div><div class="grid"><div><div class="card"><div class="profile"><div class="initial">${esc((state.name||'C').trim().slice(0,2).toUpperCase())}</div><div><h2>${esc(state.name)}</h2><p class="muted">${esc(state.address)}</p></div></div><div class="divider"></div><div class="facts"><div><small>NIT</small><b>${esc(company().nit)}</b></div><div><small>Municipio</small><b>${esc(state.city)}${state.department?' · '+esc(state.department):''}</b></div><div><small>Actividad CIIU</small><b>${esc(state.ciiu)}</b></div><div><small>Identificador piloto</small><b>${esc(siteCode())}</b></div><div><small>Teléfono de contacto</small><b>${esc(state.phone)}</b></div><div><small>Correo de contacto</small><b>${esc(state.contactEmail)}</b></div></div></div><div class="stats"><div class="stat"><b>${active.length}</b><span>Obligaciones aplicables</span></div><div class="stat"><b>${evidence}</b><span>Con evidencia demo</span></div><div class="stat"><b>${active.length-evidence}</b><span>Por revisar o verificar</span></div></div><div class="card"><div class="sectionhead" style="margin-top:0"><h2>Tu expediente digital</h2><a class="muted" href="#documentos">Ver todo →</a></div><p class="muted">La documentación es el inicio. El cumplimiento se verifica. Gestiona cada requisito desde Expediente digital.</p>${items.map(r=>checkRow(r)).join('')}</div></div><div>${identity()}${nextStepCard()}</div></div>`}
else if(route==='biblioteca'){out=libraryPage()}
else if(route==='horarios'){out=hoursPage()}
else if(route==='practicas'){out=practicesPage()}
else if(route==='documentos'){out=head('Expediente digital','Cada requisito, con su trazabilidad.','Matriz del artículo 87 · 10 numerales, desglosados en 12 controles.')+`<div class="toolbar"><input id="search" placeholder="Buscar requisito o entidad" aria-label="Buscar requisito" oninput="filterDocs()"><select id="filter" aria-label="Filtrar estado" onchange="filterDocs()"><option value="all">Todos los estados</option><option value="pending">Pendientes / por validar</option><option value="visit">Verificación en sitio</option><option value="na">No aplicables</option></select></div><div class="card" id="doclist">${items.map(r=>row(r)).join('')}</div>`}
else if(route==='cedula'){out=head('Identidad empresarial','Una cédula. Un expediente vivo.','El QR identifica el establecimiento y abre la consulta del piloto.',`<button class="btn" onclick="downloadCard()">Descargar imagen</button><button class="btn" onclick="printCard()">Descargar PDF</button>`)+traffic()+`<div class="grid"><div><div class="card"><h2>${esc(state.name)}</h2><p class="muted">${esc(state.city)} · ${esc(state.address)}</p><div class="rule"><b>C.E.D.E. ${esc(siteCode())}</b><p>La identidad puede existir con documentos pendientes. No es una licencia de funcionamiento ni declara cumplimiento integral.</p></div><h3>¿Qué puede consultar una autoridad?</h3><p class="muted">Estado por requisito, entidad responsable, fecha de la evidencia, origen y pendientes. En producción, los documentos y datos personales requerirán autenticación y permisos.</p><div class="actions"><a class="btn primary" href="#verificar">Abrir consulta IVC</a><button class="btn" onclick="copyLink()">Copiar enlace QR</button><button class="btn" onclick="downloadCard()">Descargar imagen (PNG)</button><button class="btn" onclick="printCard()">Descargar PDF o imprimir</button></div></div><div class="card"><h2>Alcance de esta demostración</h2><p class="muted">El QR abre un expediente ficticio fijo. Las modificaciones se guardan únicamente en este navegador; otro dispositivo verá los datos iniciales. El sitio y el QR son de acceso público y no muestran datos reales.</p></div></div>${identity()}</div>`}
else if(route==='alertas'){out=head('Seguimiento preventivo','Anticípate a tus actualizaciones.','Alertas internas del piloto; no se envían correos ni mensajes.')+notice()+`<div class="grid"><div><div class="card"><h2>Reglas de seguimiento</h2><div class="docrow"><div>◷</div><div><h3>Certificado mercantil · 30 días</h3><p>Recordatorio desde el día 23; actualizar si supera 30 días.</p></div>${badge(status(items[1]))}</div><div class="docrow"><div>↻</div><div><h3>Renovación anual de matrícula</h3><p>Control independiente del certificado. Seguimiento al 31 de marzo.</p></div><span class="badge">${state.renewed?'Renovación demo registrada':'Por revisar'}</span></div><div class="docrow"><div>▤</div><div><h3>Evidencia sanitaria</h3><p>${state.docs.sanidad?'Referencia recibida; pendiente validación.':'Pendiente registrar evidencia.'}</p></div>${badge(status(items[7]))}</div></div><div class="card"><h2>Renovaciones registradas</h2>${renewals()}</div><div class="card"><h2>Actividad del expediente</h2><div class="timeline">${state.events.length?state.events.map(e=>`<p>${esc(e.text)}<small>${esc(e.date)} · Acción local de demostración</small></p>`).join(''):'<p>Expediente demostrativo creado<small>Sin actuaciones oficiales registradas</small></p>'}</div></div></div><div class="card"><h2>Preferencias</h2><form onsubmit="preferences(event)"><label for="email">Correo de ejemplo</label><input type="email" id="email" value="${esc(state.email)}" placeholder="empresario@ejemplo.com"><label class="check"><input id="alerts" type="checkbox" ${state.alerts?'checked':''}> Mostrar recordatorios internos</label><p class="muted">Usa datos ficticios. No se activa ningún envío externo.</p><button class="btn primary">Guardar preferencias</button></form></div></div>`}
else if(route==='entidades'){const ents=[['CC','Cámaras de Comercio / RUES','Matrícula, renovación y actividades registradas.','Intercambio autorizado de datos por matrícula y jurisdicción.',[['Consultar el RUES','https://www.rues.org.co/']]],['OSA','Organización Sayco Acinpro','Evidencia de pago, período y repertorio cubierto.','Convenio con OSA y demás titulares o gestores según corresponda.',[['Trámite en línea','https://www.osa.org.co/']]],['PN','Policía Nacional','Constancia de comunicación de apertura.','Radicación o consulta por canal habilitado.',[['Trámites y servicios','https://www.policia.gov.co/tramites-servicios']]],['AL','Alcaldías y Planeación','Uso del suelo, destinación y horarios locales.','Catálogo de normas por municipio, zona y actividad.',[['Buscar el trámite en GOV.CO','https://www.gov.co/']]],['SS','Secretarías de Salud','Inspección sanitaria, conceptos y visitas.','Interoperabilidad con la autoridad sanitaria territorial.',[['Bogotá · Salud Capital','https://www.saludcapital.gov.co/']]],['BO','Bomberos','Concepto técnico de seguridad humana y contra incendios.','Solicitud, vigencia y consulta del concepto por establecimiento.',[['Bogotá · Bomberos','https://www.bomberosbogota.gov.co/']]],['AM','Autoridad ambiental','Ruido, vertimientos, residuos y publicidad exterior.','Interoperabilidad con la autoridad ambiental competente.',[['Bogotá · Secretaría de Ambiente','https://www.secretariadeambiente.gov.co/']]],['DI','DIAN','RUT, facturación electrónica y obligaciones tributarias.','Consulta del RUT y del estado de facturación mediante convenio.',[['RUT en línea','https://www.dian.gov.co/tramitesservicios/tramites-y-servicios/tributarios/Paginas/RUT.aspx'],['Facturación electrónica','https://catalogo-vpfe.dian.gov.co/']]],['SH','Secretarías de Hacienda','Registro de información tributaria territorial (RIT).','Inscripción y actualización según las reglas de cada municipio.',[['Bogotá · RIT','https://www.shd.gov.co/shd/rit']]],['SIC','Superintendencia de Industria y Comercio','Información de precios, propina y protección al consumidor.','Consulta de requisitos y canal de denuncias.',[['Sitio oficial','https://www.sic.gov.co/']]],['ID','IDIGER','Gestión del riesgo y planes de autoprotección en Bogotá.','Radicación y consulta según aforo y actividad.',[['Bogotá · IDIGER','https://www.idiger.gov.co/']]],['PU','PULEP','Registro de productores de espectáculos públicos de las artes escénicas.','Consulta del registro y de los eventos reportados.',[['Registro PULEP','https://pulep.mincultura.gov.co/']]],['CU','Curadurías urbanas','Licencias de construcción, adecuación y reconocimiento.','Verificación de las licencias asociadas al inmueble.',[]],['DA','DADEP','Uso y aprovechamiento del espacio público en Bogotá.','Permisos de antejardín, terrazas y mobiliario urbano.',[['Bogotá · DADEP','https://www.dadep.gov.co/']]],['NT','MinCIT / RNT y MinTIC','Requisitos especiales según la actividad.','Consulta de RNT o permisos cuando apliquen.',[['RNT en línea','https://rnt.confecamaras.co/'],['MinTIC','https://mintic.gov.co/']]]];out=head('Articulación nacional','Entidades conectadas por un propósito.','Mapa propuesto de integración. Ninguna conexión externa está activa.')+`<div class="card"><h2>¿No sabes por dónde empezar un requisito?</h2><p class="muted">Cada tarjeta enlaza el trámite en línea de la entidad cuando existe. Si prefieres que te acompañemos, escríbenos y te orientamos con el requisito que necesites.</p><a class="btn primary" target="_blank" rel="noopener" href="${wa('un requisito de mi establecimiento')}">Escribir por WhatsApp al +57 321 230 4589</a></div><div class="fullgrid">${ents.map(e=>`<div class="card entity"><div class="symbol">${e[0]}</div><h3>${e[1]}</h3><p>${e[2]}</p><span class="badge gray">Integración propuesta</span><div class="divider"></div><p>${e[3]}</p><div class="actions">${e[4].map(([label,url])=>`<a class="btn small" target="_blank" rel="noopener" href="${url}">${label} ↗</a>`).join('')}<a class="btn small primary" target="_blank" rel="noopener" href="${wa('el requisito de '+e[1])}">Pedir ayuda por WhatsApp</a></div></div>`).join('')}</div><div class="card"><h2>Una arquitectura nacional, reglas territoriales</h2><p class="muted">Cada evidencia conservará origen, fecha de expedición, vigencia, municipio, fecha de consulta y respuesta de la entidad. Una indisponibilidad se mostrará como «fuente no disponible», nunca como incumplimiento automático.</p><button class="btn" onclick="simulate()">Probar consulta simulada</button><div id="syncresult"></div></div>`}
else if(route==='verificar'){out=`<div class="verifyhead"><span class="brandmark">C</span><span class="eyebrow">Consulta de inspección, vigilancia y control</span><h1>Verifica el expediente empresarial.</h1><p class="muted">Demostración de consulta mediante QR · Sin efectos administrativos</p><form class="toolbar" style="justify-content:center" onsubmit="lookup(event)"><input id="code" value="${esc(siteCode())}" aria-label="Código C.E.D.E." required><button class="btn primary">Consultar</button></form></div><div id="verifyresult" class="verification">${verify()}</div>`}
else{out=head('Diseño del piloto','De ventanillas dispersas a una identidad.','Modelo funcional, jurídico y tecnológico para la siguiente fase.')+`<div class="card"><h2>01 · Alcance legal</h2><p>El expediente organiza requisitos previos y obligaciones durante la actividad. La C.E.D.E. propuesta no añade una licencia ni sustituye la competencia de inspección. No todas las obligaciones se acreditan con un certificado.</p><div class="rule">La actualización del certificado a 30 días es una política propuesta por Asobares, no una obligación atribuida al artículo 87. La renovación de la matrícula mercantil es anual.</div><p>Uso del suelo se evalúa por inmueble y actividad; ruido, horarios y condiciones sanitarias, ambientales y de seguridad exigen cumplimiento material. «No aplica» es una clasificación preliminar del perfil, sujeta a revisión jurídica.</p></div><div class="card"><h2>02 · Integración y seguridad de producción</h2><div class="tablewrap"><table><tr><th>Capa</th><th>Diseño propuesto</th></tr><tr><td>Identidad</td><td>Empresa y establecimientos separados; NIT, matrícula, municipio y código opaco por sede.</td></tr><tr><td>Intercambio</td><td>Adaptadores API o convenios de intercambio; como alternativa, aporte documental con validación humana.</td></tr><tr><td>Reglas</td><td>Versionadas por municipio, actividad, vigencia y fundamento normativo; sin inventar requisitos locales.</td></tr><tr><td>Expediente</td><td>Repositorio cifrado, control de versiones, huella del documento y estados separados de fuente y cumplimiento.</td></tr><tr><td>QR e IVC</td><td>URL con identificador opaco, consulta en servidor; documentos privados por rol y entidad.</td></tr><tr><td>Accesos</td><td>Empresario, delegado de entidad e inspector con autenticación fuerte, permisos y auditoría inalterable.</td></tr><tr><td>Alertas</td><td>Motor diario de vigencias, consentimiento, entrega y reintentos por correo/SMS; no habilitado aquí.</td></tr><tr><td>Datos personales</td><td>Minimización, finalidad, autorizaciones cuando procedan, retención y ejercicio de derechos.</td></tr></table></div></div><div class="card"><h2>03 · Ruta sugerida de implementación</h2><div class="facts"><div><small>Fase 1 · 0–30 días</small><b>Validar matriz y convenios</b><p class="muted">Asobares, una cámara y autoridades de una ciudad piloto.</p></div><div><small>Fase 2 · 31–60 días</small><b>Conectar y probar</b><p class="muted">Autenticación, repositorio, primer intercambio y trazabilidad.</p></div><div><small>Fase 3 · 61–90 días</small><b>Evaluar en territorio</b><p class="muted">Meta propuesta: 50 negocios. Medir tiempo de consulta, actualización y errores.</p></div></div><p class="muted">Plazos orientativos, sujetos a acuerdos, disponibilidad técnica y validación jurídica.</p></div><div class="card legal"><h2>Fuentes de referencia</h2><a target="_blank" rel="noopener" href="https://www.suin-juriscol.gov.co/clp/contenidos.dll/Leyes/30021736">Ley 1801 de 2016 · Artículo 87 · SUIN-Juriscol ↗</a><a target="_blank" rel="noopener" href="https://www.ccb.org.co/renueve-su-matricula-mercantil-en-solo-3-pasos-hasta-el-31-de-marzo-y-reciba-beneficios">Cámara de Comercio de Bogotá · Renovación anual 2026 ↗</a><p class="muted">Referencias consultadas para este diseño. La implementación institucional requiere revisión jurídica de normas especiales y territoriales.</p></div>`}$('#app').innerHTML=out;}
function verify(target){const previo=state;if(target)state=target;const salida=verifyCard();state=previo;return salida}
function verifyCard(){return traffic(false)+`<div class="card"><div class="heading"><div><span class="eyebrow">CEDE · ${esc(state.code||'DEMO-0001')}</span><h2>${esc(state.name)}</h2><p class="muted">${esc(state.city)} · ${esc(state.ciiu)}</p></div><span class="badge ${assessment().color==='green'?'pass':'warn'}">${assessment().title}</span></div><div class="rule">Consulta de datos simulados. Ninguna evidencia ha sido validada por una entidad. El estado documental no certifica el cumplimiento en sitio.</div>${items.map(r=>row(r,false)).join('')}<p class="muted">Consultado: ${new Date().toLocaleString('es-CO')} · Fuente: demostración local.</p></div>`}
function lookup(e){e.preventDefault();const codigo=$('#code').value.trim().toUpperCase(),encontrado=sites().find(([,x])=>(x.code||'').toUpperCase()===codigo);$('#verifyresult').innerHTML=encontrado?verify(encontrado[1]):`<div class="card empty">No se encontró ese código. Códigos del NIT ${esc(company().nit)}: ${sites().map(([,x])=>esc(x.code)).join(', ')}.</div>`}function filterDocs(){const term=$('#search').value.toLowerCase(),f=$('#filter').value;const found=items.filter(r=>r.join(' ').toLowerCase().includes(term)&&(f==='all'||(f==='pending'?['pending','review','stale','soon','fail'].includes(status(r)):status(r)===f)));$('#doclist').innerHTML=found.length?found.map(r=>row(r)).join(''):'<p class="empty">No hay requisitos con estos filtros.</p>'}
function openModal(html){$('#modalbody').innerHTML=html;$('#modal').showModal()}function detail(id,editable){if(id==='horarios'){location.hash='horarios';return}const r=items.find(x=>x[0]===id),d=state.docs[id];openModal(`<span class="eyebrow">${r[3]}</span><h2 style="margin-top:12px">${r[1]}</h2>${badge(status(r))}<p style="margin-top:18px">${r[4]}</p><p class="muted"><b>Responsable:</b> ${r[2]}</p><div class="rule">Origen: ${d?'referencia aportada por el usuario; sin verificar':'datos ficticios del piloto; sin respuesta de entidad'}.${d?`<br>Referencia: ${esc(d.ref)}<br>Fecha: ${esc(d.date)}${d.expires?`<br>Renovar antes de: ${esc(d.expires)}`:''}`:''}</div>${editable?`<form onsubmit="documentSave(event,'${id}')"><div class="rule"><b>Verificación de prueba</b><p>Simula una actuación de entidad; sin efectos oficiales.</p><div class="actions"><button type="button" class="btn small" onclick="checkOne('${id}','pass')">Simular cumple</button><button type="button" class="btn small" onclick="checkOne('${id}','fail')">Simular no cumple</button></div></div><label for="ref">Referencia del documento (simulación)</label><input id="ref" maxlength="120" placeholder="Ej.: RAD-DEMO-2026-001" value="${esc(d?.ref||'')}" required><label for="docdate">Fecha de expedición</label><input id="docdate" type="date" max="${today}" value="${esc(d?.date||(id==='mercantil'?state.issued:today))}" required><label for="docexpires">Fecha de renovación o vencimiento (opcional)</label><input id="docexpires" type="date" value="${esc(d?.expires||'')}"><p class="muted">Se registra una referencia local, no un archivo oficial. Quedará «Por validar». Si indicas la fecha de renovación, el piloto avisa 30 días antes y marca el control cuando se vence.</p>${fileField('doc:'+id,d?.file)}<div class="actions"><button class="btn primary">Guardar referencia</button><button type="button" class="btn" onclick="$('#modal').close()">Cerrar</button></div></form>`:`<div class="actions"><button class="btn" onclick="$('#modal').close()">Cerrar</button></div>`}`)}
async function documentSave(e,id){e.preventDefault();const date=$('#docdate').value,expires=$('#docexpires')?.value||'';if(date>today)return toast('La fecha no puede ser futura.');if(expires&&expires<=date)return toast('La renovación debe ser posterior a la fecha de expedición.');const subido=await takeFile('doc:'+id,$('#docfile'));if(subido==='error')return;const file=subido||state.docs[id]?.file||null;if(state.checks)delete state.checks[id];state.docs[id]={ref:$('#ref').value.trim(),date,expires,file};if(id==='mercantil')state.issued=date;state.events.unshift({text:'Referencia registrada: '+items.find(r=>r[0]===id)[1],date:new Date().toLocaleString('es-CO')});save();$('#modal').close();render();toast('Referencia guardada. Pendiente de validación por la entidad.')}function profile(){openModal(`<h2>Perfil del establecimiento</h2><p class="muted">Usa información ficticia para explorar el piloto. La razón social y el NIT son de la empresa y se comparten con todos sus establecimientos.</p><form onsubmit="profileSave(event)"><label>Razón social<input id="prazon" value="${esc(company().razon)}" required maxlength="140"></label><label>NIT<input id="pnit" value="${esc(company().nit)}" required maxlength="20" placeholder="Ej.: 901.234.567-8"></label><label>Nombre del establecimiento<input id="pname" value="${esc(state.name)}" required maxlength="100"></label><label>Municipio<input id="pcity" required maxlength="100" value="${esc(state.city)}" placeholder="Ej.: Zipaquirá"></label><label for="pdept">Departamento</label><select id="pdept" required style="max-width:100%"><option value="">Selecciona un departamento</option>${departments.map(d=>`<option ${state.department===d?'selected':''}>${d}</option>`).join('')}</select><label>Dirección<input id="paddress" value="${esc(state.address)}" required maxlength="140"></label><label>Teléfono de contacto<input id="pphone" type="tel" value="${esc(state.phone)}" required maxlength="40" placeholder="Ej.: +57 601 123 4567"></label><label>Correo de contacto<input id="pcontact" type="email" value="${esc(state.contactEmail)}" required maxlength="120" placeholder="Ej.: contacto@establecimiento.co"></label><label class="check"><input id="photel" type="checkbox" ${state.hotel?'checked':''}> Ofrece alojamiento u hospitalidad</label><div class="actions"><button class="btn primary">Guardar perfil</button><button class="btn" type="button" onclick="$('#modal').close()">Cancelar</button></div></form>`)}function profileSave(e){e.preventDefault();store.company.razon=$('#prazon').value.trim();store.company.nit=$('#pnit').value.trim();state.name=$('#pname').value.trim();const nextCity=$('#pcity').value,nextDept=$('#pdept').value;if(nextCity!==state.city||nextDept!==state.department){delete state.checks?.horarios;state.hoursZone='unknown'}state.city=nextCity;state.department=nextDept;state.address=$('#paddress').value.trim();state.phone=$('#pphone').value.trim();state.contactEmail=$('#pcontact').value.trim();state.hotel=$('#photel').checked;save();$('#modal').close();render();toast('Perfil actualizado. Aplicabilidad recalculada.')}function preferences(e){e.preventDefault();state.email=$('#email').value;state.alerts=$('#alerts').checked;save();toast('Preferencias guardadas en este navegador. No se enviarán mensajes.')}async function copyLink(){try{await navigator.clipboard.writeText(location.origin+location.pathname+'#verificar');toast('Enlace del QR copiado.')}catch{toast('Abre Consulta IVC y copia la dirección del navegador.')}}function simulate(){$('#syncresult').innerHTML='<div class="rule"><b>Resultado de prueba: fuente no conectada.</b><p>No hay convenios ni credenciales configurados. Se conserva el expediente sin atribuir validaciones oficiales.</p></div>'}window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});

function assessment(){const relevant=items.filter(r=>status(r)!=='na'),passed=relevant.filter(r=>status(r)==='pass').length,failed=relevant.filter(r=>status(r)==='fail').length;const critical=relevant.filter(r=>['suelo','mercantil','seguridad','sanidad'].includes(r[0])&&(status(r)==='fail'||(r[0]==='mercantil'&&!state.renewed)));const color=critical.length||failed>relevant.length/2?'red':passed===relevant.length?'green':'yellow';return {color,passed,total:relevant.length,failed,title:color==='red'?'Rojo · Requiere acción prioritaria':color==='green'?'Verde · ¡Felicitaciones!':'Amarillo · Completa la verificación',desc:color==='green'?'¡Felicitaciones! Tu establecimiento tiene todos los requisitos aplicables verificados en esta simulación. Mantén tus evidencias actualizadas.':color==='red'?'Existe un incumplimiento crítico o más de la mitad de las obligaciones tienen incumplimiento registrado en la simulación.':'Hay requisitos pendientes, documentos por actualizar o condiciones que requieren verificación. Un pendiente no equivale a un incumplimiento.'}}
function traffic(controls=true){const a=assessment();return `<section class="traffic ${a.color}" aria-label="Semáforo de cumplimiento ${a.color}"><div class="lights" aria-hidden="true">${['red','yellow','green'].map(c=>`<span class="light ${c} ${a.color===c?'on':''}"></span>`).join('')}</div><div><h2>${a.title}</h2><p>${a.desc}</p><p style="margin-top:6px"><b>Semáforo demostrativo · Sin validación oficial</b></p>${controls?`<div class="demo-controls"><button class="btn small" onclick="scenario('red')">Probar rojo</button><button class="btn small" onclick="scenario('yellow')">Probar amarillo</button><button class="btn small" onclick="scenario('green')">Probar verde</button><button class="btn small" onclick="criteria()">Ver criterios</button></div>`:''}</div><div class="score">${a.passed}/${a.total}<div style="font-size:11px;font-weight:400">verificados (demo)</div></div></section>${meritSummary(controls)}`}
function scenario(color){state.checks={};state.docs={};state.renewed=true;state.issued=ago(color==='yellow'?27:0);items.filter(r=>status(r)!=='na').forEach((r,i)=>{state.checks[r[0]]=color==='green'?'pass':color==='red'?'fail':i<4?'pass':undefined});state.events.unshift({text:'Escenario de semáforo: '+({red:'rojo',yellow:'amarillo',green:'verde'}[color]),date:new Date().toLocaleString('es-CO')});save();render();toast('Escenario de prueba aplicado; no es una validación oficial.')}
function checkOne(id,value){state.checks=state.checks||{};state.checks[id]=value;state.events.unshift({text:'Verificación simulada: '+items.find(r=>r[0]===id)[1]+' · '+(value==='pass'?'cumple':'no cumple'),date:new Date().toLocaleString('es-CO')});save();$('#modal').close();render();toast('Verificación simulada registrada.')}
function criteria(){openModal(`<h2>Criterios del semáforo</h2><p><b>Rojo:</b> incumplimiento registrado en más del 50% de los controles aplicables, o en cualquiera de los críticos: uso del suelo, matrícula vigente, seguridad o sanidad.</p><p><b>Amarillo:</b> cualquier pendiente, revisión en sitio, evidencia de más de 30 días o incumplimiento no crítico que no alcance el umbral rojo.</p><p><b>Verde:</b> el 100% de los controles aplicables verificados y evidencia mercantil de máximo 30 días. Activa una felicitación.</p><div class="rule">Perfil inicial: 10 controles aplicables; 6 incumplimientos activan rojo por mayoría. Los 4 controles críticos activan rojo individualmente. Los «No aplica» se excluyen del total.</div><p class="muted">Criterio operativo propuesto por Asobares, no clasificación sancionatoria legal. El piloto permite simular verificaciones; en producción solo las entidades competentes y usuarios autorizados podrán registrarlas.</p><button class="btn primary" onclick="$('#modal').close()">Entendido</button>`)}

const practices=[
{id:'conductor',name:'Conductores elegidos para clientes',points:15,group:'Regreso seguro',proof:'Convenio activo, canal de solicitud y registro anonimizado de disponibilidad del servicio.'},
{id:'agua',name:'Hidratación de cortesía',points:10,group:'Cuidado del cliente',proof:'Protocolo de agua potable gratuita, comunicación visible al cliente y evidencia de disponibilidad.'},
{id:'parqueadero',name:'Alianza con parqueaderos',points:10,group:'Regreso seguro',proof:'Acuerdo vigente, horarios, ubicación e información para que el vehículo pueda permanecer si su conductor no debe conducir.'},
{id:'taxi',name:'Taxis seguros verificados',points:15,group:'Regreso seguro',proof:'Alianza con operador y protocolo para verificar vehículo y conductor antes del abordaje, con cuidado de datos personales.'},
{id:'formacion',name:'Formaciones organizadas por Asobares',points:20,group:'Equipo preparado',proof:'Constancias de al menos dos formaciones distintas en los últimos 12 meses, con participación conjunta de un responsable y personal operativo.'},
{id:'cuidado',name:'IMPLEMENTACIÓN DEL PROGRAMA “PREGUNTA POR ÁNGELA”' ,points:10,group:'Cuidado del cliente',proof:'Evidencia de implementación del programa Pregunta por Ángela: personal formado, responsable por turno, material visible y simulacro. Consulta el protocolo en Biblioteca.'},
{id:'sinalcohol',name:'Opciones atractivas sin alcohol',points:5,group:'Cuidado del cliente',proof:'Carta con al menos tres opciones sin alcohol claramente identificadas y disponibles.'},
{id:'vecinos',name:'Acuerdo de convivencia con vecinos',points:5,group:'Entorno y comunidad',proof:'Canal de atención, responsable y registro de seguimiento de acuerdos. No reemplaza los límites legales de ruido.'},
{id:'inclusion',name:'Formación en atención inclusiva',points:5,group:'Equipo preparado',proof:'Taller específico y protocolo de atención inclusiva, adicional al cumplimiento obligatorio. No reutilizar constancias ya puntuadas.'},
{id:'circular',name:'Alianza de aprovechamiento de residuos',points:5,group:'Entorno y comunidad',proof:'Acuerdo con un aliado y reporte de resultados de aprovechamiento, adicional a las obligaciones ambientales.'}
];
function practiceStatus(id){const p=state.practices?.[id];if(!p)return 'none';if(!p.until||p.until<today)return 'expired';return p.validated?'verified':'review'}
function merit(){const score=practices.reduce((n,p)=>n+(practiceStatus(p.id)==='verified'?p.points:0),0);return {score,level:score>=90?'Excelencia':score>=70?'Destacado':score>=40?'Comprometido':'En camino',eligible:assessment().color==='green'&&score>=40}}
function meritSummary(editable=true){const m=merit();return `<section class="merit-summary"><div><span class="eyebrow">Buenas prácticas · Puntos adicionales</span><h2>${m.score}/100 <span>· ${m.level}</span></h2><p>${m.eligible?'¡Felicitaciones! Cumplimiento en verde y buenas prácticas: reconocimiento '+m.level+' en esta simulación.':m.score>=40?'Puntaje acumulado. Reconocimiento condicionado a alcanzar el semáforo verde.':'Suma puntos por cuidar a tus clientes, a tu equipo y a tu entorno.'}</p><p class="muted">Puntaje piloto; no modifica el color legal ni compensa incumplimientos.</p></div>${editable?'<a class="btn primary" href="#practicas">Gestionar puntos →</a>':'<span class="badge gray">Reconocimiento de demostración</span>'}</section>`}
function practicesPage(){const m=merit();return head('C.E.D.E. + · Buenas prácticas','Cumplir es el comienzo. Cuidar suma.','Modelo propuesto por Asobares · Hasta 100 puntos adicionales.')+meritSummary(false)+`<div class="card"><h2>Cómo se suman los puntos</h2><p class="muted">Registra una evidencia y su fecha de revisión. Solo una evidencia vigente y validada en la simulación suma puntos. Cada práctica puntúa una vez; una misma constancia no puede justificar dos prácticas.</p><div class="levels"><span>0–39 · En camino</span><span>40–69 · Comprometido</span><span>70–89 · Destacado</span><span>90–100 · Excelencia</span></div><div class="bar"><span style="width:${m.score}%"></span></div><p class="muted">El reconocimiento requiere además semáforo verde. Los puntos se conservan con rojo o amarillo, pero el reconocimiento queda suspendido.</p></div><div class="practice-grid">${practices.map(p=>{const st=practiceStatus(p.id),entry=state.practices?.[p.id];return `<article class="card practice-card"><div class="practice-top"><span class="eyebrow">${p.group}</span><strong>+${p.points}</strong></div><h2>${p.name}</h2><p class="muted">${p.proof}</p><span class="badge ${st==='verified'?'pass':st==='none'?'gray':'warn'}">${{verified:'Suma puntos · validación simulada',none:'Sin registrar',review:'Por validar · 0 puntos',expired:'Revisión vencida · 0 puntos'}[st]}</span>${entry?`<p class="muted" style="margin-top:12px">Revisar antes de: ${esc(entry.until)}</p>`:''}<div class="actions"><button class="btn small" onclick="practiceDetail('${p.id}')">${entry?'Revisar evidencia':'Registrar evidencia'}</button>${st==='review'?`<button class="btn small primary" onclick="validatePractice('${p.id}')">Validar</button>`:''}</div></article>`}).join('')}</div><div class="rule">Las prácticas no crean excepciones a obligaciones de seguridad, accesibilidad, convivencia, ambiente o protección del cliente. El reconocimiento propuesto no es una certificación oficial de Asobares.</div>`}
function practiceDetail(id){const p=practices.find(p=>p.id===id),v=state.practices?.[id];openModal(`<span class="eyebrow">Buenas prácticas · +${p.points} puntos</span><h2 style="margin-top:12px">${p.name}</h2><p class="muted">${p.proof}</p><form onsubmit="savePractice(event,'${id}')"><label for="pref">Referencia de evidencia ficticia</label><input id="pref" required maxlength="160" value="${esc(v?.ref||'')}" placeholder="Ej.: CONVENIO-DEMO-001"><label for="pdate">Fecha de evidencia</label><input type="date" id="pdate" required max="${today}" value="${esc(v?.date||today)}"><label for="puntil">Vigente / revisar hasta</label><input type="date" id="puntil" required value="${esc(v?.until||'')}"><p class="muted">Máximo 12 meses desde la evidencia; usa el plazo menor si el convenio vence antes.</p>${fileField('practica:'+id,v?.file)}<div class="actions"><button class="btn primary">Guardar por validar</button>${v?`<button type="button" class="btn" onclick="validatePractice('${id}')">Simular validación</button><button type="button" class="btn" onclick="removePractice('${id}')">Retirar práctica</button>`:''}<button type="button" class="btn" onclick="$('#modal').close()">Cerrar</button></div></form>`)}
async function savePractice(e,id){e.preventDefault();const ref=$('#pref').value.trim(),date=$('#pdate').value,until=$('#puntil').value;const maxDate=new Date(date+'T12:00:00Z');maxDate.setUTCFullYear(maxDate.getUTCFullYear()+1);if(!ref||!date||!until||date>today||until<date||until>maxDate.toISOString().slice(0,10))return toast('Revisa las fechas: evidencia no futura y revisión de máximo 12 meses.');if(Object.entries(state.practices||{}).some(([key,v])=>key!==id&&v.ref.toLowerCase()===ref.toLowerCase()))return toast('Esa referencia ya está registrada en otra práctica.');const subido=await takeFile('practica:'+id,$('#docfile'));if(subido==='error')return;state.practices=state.practices||{};state.practices[id]={ref,date,until,validated:false,file:subido||state.practices?.[id]?.file||null};logPractice(id,'Evidencia registrada por validar');save();$('#modal').close();render();toast('Evidencia registrada. Simula su validación para sumar puntos.')}
function validatePractice(id){const p=state.practices?.[id];if(!p||p.until<today)return toast('Actualiza la evidencia vencida antes de validarla.');p.validated=true;logPractice(id,'Validación simulada');save();$('#modal').close();render();toast('Puntos actualizados. El semáforo legal conserva sus criterios.')}
function removePractice(id){delete state.practices[id];logPractice(id,'Práctica retirada');save();$('#modal').close();render();toast('Práctica retirada y puntaje recalculado.')}
function logPractice(id,action){state.events.unshift({text:action+': '+practices.find(p=>p.id===id).name,date:new Date().toLocaleString('es-CO')})}
function libraryPage(){return head('Biblioteca Asobares','El conocimiento también cuida tu negocio.','Normativa, programas, protocolos y formación · Fuentes revisadas el 18/09/2026.')+`<div class="card"><h2>Biblioteca de registro Asobares</h2><p class="muted">Este catálogo reúne los recursos citados por el piloto. El registro de formación y las capacitaciones del gremio están en el portal institucional.</p><a class="btn primary" target="_blank" rel="noopener" href="https://asobares-biblioteca.vercel.app/">Abrir la Biblioteca Asobares ↗</a></div><div class="toolbar"><input id="libsearch" placeholder="Buscar: Ángela, DIAN, sanitaria…" aria-label="Buscar en biblioteca" oninput="filterLibrary()"><select id="libcategory" aria-label="Categoría" onchange="filterLibrary()"><option value="all">Todas las categorías</option>${[...new Set(resources.map(r=>r.category))].map(c=>`<option>${c}</option>`).join('')}</select></div><p class="muted" id="libcount">${resources.length} recursos</p><div class="practice-grid" id="libresults">${resourceCards(resources)}</div>`}
function resourceCards(rows){return rows.map(r=>`<article class="card practice-card"><span class="eyebrow">${esc(r.category)} · ${r.format}</span><h2>${esc(r.title)}</h2><p class="muted">${esc(r.note)}</p><div class="actions"><a class="btn primary" href="${esc(r.url)}" target="_blank" rel="noopener">${r.local?'Abrir PDF':'Abrir documento'} ↗</a>${r.local?`<a class="btn" href="${esc(r.url)}" download>Descargar</a>`:''}<a class="btn small" href="${esc(r.source)}" target="_blank" rel="noopener">Fuente</a></div></article>`).join('')||'<p class="empty">No hay documentos con esos filtros.</p>'}
function filterLibrary(){const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),q=normalize($('#libsearch').value),cat=$('#libcategory').value,rows=resources.filter(r=>(cat==='all'||r.category===cat)&&normalize(r.title+' '+r.note).includes(q));$('#libresults').innerHTML=resourceCards(rows);$('#libcount').textContent=rows.length+' recursos'}
function isBogota(){return state.city.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes('bogota')}
function hoursPage(){const bog=isBogota();return head('Normativa territorial','El horario depende de dónde estás.','Identifica el municipio, la actividad y la zona antes de aplicar una norma.')+`<div class="card"><form onsubmit="saveHours(event)"><div class="facts"><div><label for="hcity">Ciudad o municipio</label><input id="hcity" required maxlength="100" value="${esc(state.city)}" placeholder="Ej.: Zipaquirá"></div><div><label for="hdept">Departamento</label><input id="hdept" required maxlength="80" value="${esc(state.department||(bog?'Bogotá D.C.':''))}" placeholder="Ej.: Cundinamarca"></div><div><label for="htype">Tipo de actividad</label><select id="htype">${[['bar','Bar / discoteca'],['general','Expendio general de alcohol'],['restaurant','Restaurante con alcohol acompañante']].map(([v,t])=>`<option value="${v}" ${(state.hoursType||'bar')===v?'selected':''}>${t}</option>`).join('')}</select></div></div><label for="hzone">¿Está dentro de una zona de horario extendido?</label><select id="hzone"><option value="unknown">Pendiente de verificar</option><option value="outside" ${state.hoursZone==='outside'?'selected':''}>Fuera de zona (declarado)</option><option value="inside" ${state.hoursZone==='inside'?'selected':''}>Dentro de zona (declarado; requiere soporte)</option></select><div class="actions" style="margin-top:20px"><button class="btn primary">Consultar municipio</button><a class="btn" href="#documentos">Volver al expediente</a></div></form></div><div class="card"><span class="eyebrow">${esc(state.city)} · ${bog?'Investigación documentada':'Investigación pendiente'}</span>${bog?bogotaHours():`<h2 style="margin-top:15px">Aún no hay una norma verificada para este municipio.</h2><p>No se aplican los horarios de Bogotá. Consulta el último acto y sus modificaciones en la alcaldía, Gobierno o Seguridad del municipio.</p><p class="muted">Este piloto tiene investigación incorporada para Bogotá. La búsqueda de otros municipios abre una consulta externa; no realiza investigación automática ni certifica vigencia.</p>`}<div class="actions" style="margin-top:20px"><a class="btn" target="_blank" rel="noopener" href="https://www.google.com/search?q=${encodeURIComponent('site:gov.co '+state.city+' '+(state.department||'')+' último decreto horario funcionamiento bares discotecas alcaldía secretaría gobierno seguridad 2026')}">Buscar novedades oficiales ↗</a></div></div><div class="card"><h2>Evidencia y verificación del horario</h2><p class="muted">Registra el acto o la constancia que soporta tu horario y simula la actuación de la entidad. Es el mismo control «Horarios de funcionamiento» del expediente.</p>${badge(status(items.find(r=>r[0]==='horarios')))}<div class="rule"><b>Verificación de prueba</b><p>Simula una actuación de entidad; sin efectos oficiales.</p><div class="actions"><button type="button" class="btn small" onclick="checkOne('horarios','pass')">Simular cumple</button><button type="button" class="btn small" onclick="checkOne('horarios','fail')">Simular no cumple</button></div></div><form onsubmit="documentSave(event,'horarios')"><label for="ref">Referencia del documento (simulación)</label><input id="ref" maxlength="120" placeholder="Ej.: Decreto 183 de 2026" value="${esc(state.docs.horarios?.ref||'')}" required><label for="docdate">Fecha de expedición</label><input id="docdate" type="date" max="${today}" value="${esc(state.docs.horarios?.date||today)}" required><label for="docexpires">Fecha de renovación o vencimiento (opcional)</label><input id="docexpires" type="date" value="${esc(state.docs.horarios?.expires||'')}">${fileField('doc:horarios',state.docs.horarios?.file)}<div class="actions"><button class="btn primary">Guardar referencia</button></div></form></div><div class="rule">La norma localizada no demuestra cumplimiento del establecimiento. Hay que revisar zona, uso del suelo, actividad real, restricciones temporales y medidas particulares. Cambiar el municipio o la actividad elimina la verificación previa del horario en el piloto.</div>`}
function bogotaHours(){const t=state.hoursType||'bar',z=state.hoursZone||'unknown';let result=t==='restaurant'?'El artículo 97 contempla una excepción para restaurantes que venden alcohol como acompañante de comidas; exige verificar la actividad principal.':t==='bar'?'Horario ordinario de referencia: 10:00 a. m. a 3:00 a. m. del día siguiente.':'Horario general de referencia: 8:00 a. m. a 12:59 a. m. del día siguiente.';if(z==='inside'&&t!=='restaurant')result+=' Posible extensión hasta las 5:00 a. m., sujeta a comprobar inclusión y condiciones de la zona; la declaración no la autoriza.';return `<h2 style="margin-top:14px">Decreto 183 de 2026 · última modificación localizada</h2><p class="muted">Alcaldía Mayor de Bogotá · Expedido y vigente desde 25/05/2026 · Investigación: 18/09/2026.</p><div class="rule"><b>${result}</b>${z==='unknown'?'<p>Zona sin verificar: no se confirma derecho a horario extendido.</p>':''}</div><p class="muted">Modifica los artículos 96, 98 y 104 del Decreto 644 de 2025. Para bares y discotecas, consultar también el artículo 97. El Decreto 293 de 2025 figura derogado y compilado.</p><div class="actions"><a class="btn small" target="_blank" rel="noopener" href="https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=193251">Decreto 183 de 2026 ↗</a><a class="btn small" target="_blank" rel="noopener" href="https://www.alcaldiabogota.gov.co/sisjur/normas/Norma1.jsp?i=191864">Decreto 644 consolidado y zonas ↗</a></div><p class="muted" style="margin-top:16px">La revisión no garantiza ausencia de actos posteriores o restricciones especiales. Abrir la fuente para comprobar novedades antes de operar.</p>`}
function saveHours(e){e.preventDefault();const city=$('#hcity').value.trim(),dept=$('#hdept').value.trim(),type=$('#htype').value,zone=$('#hzone').value;if(!city||!dept)return toast('Indica municipio y departamento.');if(city!==state.city||dept!==state.department||type!==state.hoursType||zone!==state.hoursZone){if(state.checks)delete state.checks.horarios;delete state.docs.horarios}state.city=city;state.department=dept;state.hoursType=type;state.hoursZone=zone;save();render();toast(isBogota()?'Investigación de Bogotá disponible. Revisa las condiciones.':'Municipio registrado; norma local pendiente de investigación.')}
render();
